module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic [2:0] s,
    output logic       fr2,
    output logic       fr1,
    output logic       fr0,
    output logic       dfr
);

    logic [1:0] level, next_level;
    logic [1:0] current_level;

    // Determine current water level from thermometer-coded sensors
    always_comb begin
        case (s)
            3'b000: level = 2'd0; // Below s[0]
            3'b001: level = 2'd1; // Between s[1] and s[0]
            3'b011: level = 2'd2; // Between s[2] and s[1]
            3'b111: level = 2'd3; // Above s[2]
            default: level = 2'd0;
        endcase
    end

    assign next_level = level;

    // Nominal flow rate outputs based on current water level
    always_comb begin
        case (level)
            2'd3: begin // Above s[2]
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b0;
            end
            2'd2: begin // Between s[2] and s[1]
                fr2 = 1'b0;
                fr1 = 1'b0;
                fr0 = 1'b1;
            end
            2'd1: begin // Between s[1] and s[0]
                fr2 = 1'b0;
                fr1 = 1'b1;
                fr0 = 1'b1;
            end
            2'd0: begin // Below s[0]
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
            end
            default: begin
                fr2 = 1'b1;
                fr1 = 1'b1;
                fr0 = 1'b1;
            end
        endcase
    end

    // Sequential logic for level tracking and supplemental flow rate (dfr) control
    always_ff @(posedge clk) begin
        if (reset) begin
            current_level <= 2'd0;
            dfr           <= 1'b1; // Low for a long time: all four outputs asserted
        end else begin
            if (next_level > current_level) begin
                dfr <= 1'b1; // Water level increased (previous was lower)
            end else if (next_level < current_level) begin
                dfr <= 1'b0; // Water level decreased (previous was higher)
            end
            current_level <= next_level;
        end
    end

endmodule

